(function(){'use strict';
const root=document.getElementById('wga-root'),db=window.WGA_DATA,extra=window.MEINKRAUT_CONTENT||{};
if(!root||!db){if(root)root.textContent='Das Gewürzregal konnte nicht geladen werden. Bitte lade die Seite erneut.';return;}
const config=window.MEINKRAUT_CONFIG||{},base=config.base||'./',logo=base+'assets/mein-kraut-logo-640.webp?v=final-1',icons=window.WGA_ASSET_BASE||'assets/icons/';
const ingredients=new Map(db.ingredients.map(i=>[i.id,i])),countryMap=new Map(db.countries.map(c=>[c.code,c]));
const recipes=[...(extra.mixes||[]),...db.recipes],recipeMap=new Map(recipes.map(r=>[r.id,r]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch(_){return f;}};
const initial=read('meinkraut:regal:v1',null),old=k=>read('wga2:'+k,[]);
const validIds=(arr,map)=>new Set((Array.isArray(arr)?arr:[]).filter(x=>map.has(x)));
let s={menuOpen:false,page:'start',search:'',kind:'Alle',country:'Alle',continent:'Alle',ownedOnly:false,group:'Alle',countryCode:'DE',regionId:'TW',pageNo:1,modal:'',recipeFactor:1,unit:'g',target:100,customName:'Meine Mischung',parts:[],workRecipe:null,checked:new Set(),pantry:validIds(initial?.pantry||old('pantry'),ingredients),basket:validIds(initial?.basket||old('basket'),ingredients),favorites:validIds(initial?.favorites||old('favorites'),recipeMap),saved:[],prices:initial?.prices||{},labelDate:new Date().toLocaleDateString('de-DE')};
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=t=>String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss');
const number=(n,d=2)=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:d});
const euro=n=>Number(n).toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const name=id=>ingredients.get(id)?.name||id;
const flag=code=>/^[A-Z]{2}$/.test(code)?[...code].map(c=>String.fromCodePoint(c.charCodeAt(0)+127397)).join(''):'🌍';
const density={'schwarzer-pfeffer':2.3,'weier-pfeffer':2.4,'paprika-edelsu':2.3,'paprika-gerauchert':2.3,'knoblauchgranulat':3,'zwiebelgranulat':2.5,'oregano':1,'basilikum':.7,'rosmarin':1.2,'majoran':.6,'thymian':.8,'salbei':.7,'kreuzkummel':2.1,'koriandersaat':1.8,'kurkuma':2.5,'ingwer-gemahlen':1.8,'zimt':2.6,'cayennepfeffer':2,'chiliflocken':1.7,'piment':2,'salz':6,'meersalz':6,'zucker':4,'brauner-zucker':4,'senfmehl':2.5,'muskat':2.2};
density.rauchpaprika=2.3;density.ingwer=1.8;density.senfpulver=2.5;density.muskatnuss=2.2;
const conversion=id=>density[id]||null;
const dryIds=new Set((extra.mixes||[]).flatMap(r=>r.ingredients.map(p=>p.ingredient)));
const dryIngredient=i=>dryIds.has(i.id)||(i.group==='Gewürze & Kräuter'&&['ganz','gemahlen','getrocknet','Flocken','granuliert','Stange oder gemahlen','grüne Kapseln','Kapseln','Samen','Fäden','Samen/gemahlen','trocken'].includes(i.form))||['salz','meersalz','zucker','brauner-zucker','palmzucker','kokosblutenzucker'].includes(i.id);
function validateSaved(r){return r&&typeof r.id==='string'&&typeof r.name==='string'&&Array.isArray(r.parts)&&r.parts.length>0&&r.parts.length<100&&r.parts.every(p=>ingredients.has(p.id)&&typeof p.grams==='number'&&Number.isFinite(p.grams)&&p.grams>=0&&p.grams<=10000)&&Number.isFinite(r.target)&&r.target>0&&r.target<=5000&&(!r.label||!window.MEINKRAUT_COMMERCE||window.MEINKRAUT_COMMERCE.validateLabel(r.label));}
s.saved=(Array.isArray(initial?.saved)?initial.saved:[]).filter(validateSaved).slice(0,200);
function save(){try{localStorage.setItem('meinkraut:regal:v1',JSON.stringify({schema:1,pantry:[...s.pantry],basket:[...s.basket],favorites:[...s.favorites],saved:s.saved,prices:s.prices}));return true;}catch(_){toast('Speichern auf diesem Gerät ist gerade nicht möglich. Sichere dein Regal über Export.');return false;}}
const button=(text,action,id='',cls='')=>`<button class="mk-btn ${cls}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${text}</button>`;
const nav=(text,page,cls='')=>`<button class="mk-btn ${cls}" data-nav="${page}">${text}</button>`;
function photo(id,cls=''){const i=typeof id==='string'?ingredients.get(id):id;if(!i)return '';return `<img class="mk-photo ${cls}" src="${esc(window.WGA_PHOTOS?.[i.photo]||icons+i.photo+'.webp?v=3.0.2')}" alt="Symbolbild: ${esc(i.name)}" loading="eager" decoding="async" width="65" height="65">`;}
function sourceLinks(sources){return (sources||[]).filter(x=>x?.url&&/^https?:\/\//.test(x.url)).map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc((x.author?x.author+' – ':'')+(x.title||x.url))}</a></li>`).join('');}
function editorialLabel(r){const label=r?.editorialType||'Redaktionelle Hausvariante';return label.startsWith('Veröffentlichte Autorenvariante;')?'Veröffentlichte Autorenvariante':label;}
function recipeSources(r){const links=sourceLinks(r?.sources);return links?`<section class="mk-recipe-sources"><h3>Quelle & Rezeptur</h3><ul class="mk-source">${links}</ul></section>`:'';}
function recipeNotes(r){return r?.safetyNotes?.length?`<details open><summary>Lagerung & Zutatenhinweise</summary><ul>${r.safetyNotes.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:'';}
function recipeCopyText(r,factor=1){return r.name+'\n'+r.ingredients.map(p=>`${number(p.amount*factor)} ${p.unit} ${name(p.ingredient)}`).join('\n')+'\n\n'+(r.methodSteps||[r.method]).join('\n')+'\n\n'+(r.safetyNotes||[]).join('\n')+'\n'+editorialLabel(r)+'\n'+(r.reviewStatus||'')+'\n'+(r.sources||[]).filter(x=>/^https?:\/\//.test(x.url||'')).map(x=>(x.author?x.author+' – ':'')+(x.title||'Quelle')+': '+x.url).join('\n')+'\nMein Kraut – meinkraut.odpc.de';}

const search=(placeholder='Suchen …')=>`<input type="search" class="mk-search" data-field="search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(s.search)}">`;
function title(k,t,p){return `<div class="mk-eyebrow">${k}</div><h1>${t}</h1><p class="mk-lead">${p}</p>`;}
const priceRows=[
['Basilikum',35,4.35,'https://www.kahler-berlin.de/basilikum-gerebelt-6010809'],
['Oregano',30,5.90,'https://www.kahler-berlin.de/oregano-gerebelt-ursprung-griechenland-6077409'],
['Rosmarin',15,3.90,'https://www.kahler-berlin.de/rosmarin-geschnitten-6027609'],
['Majoran',10,8.45,'https://www.kahler-berlin.de/thueringer-majoran-gerebelt-6021509'],
['Thymian',7,4.85,'https://www.kahler-berlin.de/thymian-gerebelt-6032609'],
['Salbei',3,11.50,'https://www.pikantum.de/Salbei-geschnitten-500g']];
const ingredientCost100=priceRows.reduce((sum,[,grams,price])=>sum+grams*price/500,0),comparisonPrice=5.49;
function savingsTeaser(){return `<section class="mk-savings" aria-label="Konkretes Preisbeispiel"><div><div class="mk-eyebrow">So groß kann der Unterschied sein</div><h2>Gleiche Menge.<br>Dein eigener Mix.</h2><p>Beispiel: 25 g italienische Kräuter</p></div><div class="mk-savings-prices"><div><span>Ankerkraut · fertig im Glas</span><strong>${euro(comparisonPrice)}</strong></div><div class="mk-own-price"><span>Selbst gemischt · nur Zutaten</span><strong>${euro(ingredientCost100/4)}</strong></div></div><div class="mk-savings-result"><b>${euro(comparisonPrice-ingredientCost100/4)}</b><span>Differenz pro 25 g</span><strong>rund ${number((1-ingredientCost100/4/comparisonPrice)*100,0)} % im Beispiel</strong>${nav('Die ganze Rechnung →','kosten','primary')}</div><p class="mk-savings-note">Eigene Hausrezeptur aus denselben sechs Kräuterarten, andere Mengenverhältnisse. Zutaten aus 500-g-Packungen gegenüber fertiger Markenmischung im Glas. Ohne eigene Gläser, Etiketten, Versand, Arbeitszeit, Restvorräte und späteren Datenbankzugang. Stand: 21.10.2026. Kein pauschales Sparversprechen.</p></section>`;}
function occasions(){return `<section class="mk-section"><div class="mk-eyebrow">Mehr als würzen</div><h2>Zum Zusammenmachen. Zum Verschenken. Zum Stolzsein.</h2><div class="mk-grid"><article class="mk-card"><span class="mk-badge">Familienzeit</span><h3>Heute machen wir unser eigenes Gewürz.</h3><p>Gemeinsam Kräuter entdecken, Mengen abwiegen, mischen und ein Etikett gestalten. Kinder entscheiden mit: Wie soll unsere Familienmischung heißen?</p><p class="mk-muted">Erwachsene begleiten das Mischen und übernehmen Mühle, Mixer und scharfe Gewürze. Zum Einstieg eignen sich milde Kräuter; probiert sie gemeinsam im fertigen Essen.</p>${button('Mit italienischen Kräutern starten →','price-mix','','soft')}</article><article class="mk-card"><span class="mk-badge">Weihnachten & Mitbringsel</span><h3>Ein Geschenk mit deinem Namen drauf.</h3><p>Ein selbst entwickeltes Weihnachtsgewürz, eine Mischung für Glühwein oder alkoholfreien Punsch: Im beschrifteten Glas verschenkst du etwas, das du selbst gemacht hast.</p><p>Dein Etikett hält Zutaten und Mischdatum fest. Die genaue Rezeptur kannst du dazulegen – zum Nachmischen und Weiterfreuen.</p>${button('Eigene Geschenkidee entwickeln →','blank','','soft')}</article><article class="mk-card"><span class="mk-badge">Zur nächsten Grillparty</span><h3>Bring deinen eigenen Steakpfeffer mit.</h3><p>Mehr Pfeffer? Weniger Salz? Genau deine Mischung. Gib ihr einen Namen und bring ein persönliches Glas zur nächsten Barbecue-Einladung mit.</p><p>Speichere deine Variante. Wenn jemand nach dem Rezept fragt, hast du jede Zutat und jede Grammangabe parat.</p>${button('Meinen Steakpfeffer mischen →','mix','mk-steakpfeffer','soft')}</article></div></section>`;}
function header(){return `<div class="mk-ribbon">DIE WELT IM GEWÜRZREGAL · KOSTENLOSE TESTPHASE · OHNE REGISTRIERUNG</div><header class="mk-header"><button class="mk-brand" data-nav="start" aria-label="Mein Kraut Startseite"><img src="${base}assets/mein-kraut-logo-192.webp?v=final-1" alt="Mein Kraut – Gewürze selbst mischen, mit Steinmörser und Gewürzen" width="82" height="82"><span><b>Mein Kraut</b><small>Dein Geschmack.</small><span class="mk-brand-slogan" lang="en">My Spice. Your Taste.</span></span></button><button class="mk-btn mk-menu-toggle" data-action="menu" aria-label="Menü öffnen oder schließen" aria-expanded="${s.menuOpen}" aria-controls="mk-navigation">☰</button><nav id="mk-navigation" class="mk-nav" data-open="${s.menuOpen}" aria-label="Hauptnavigation">${[['start','Start'],['rezepte','Mischungen'],['werkstatt','Mischküche'],['laender','Weltreise'],['regal','Mein Regal'],['wissen','Gewürzwissen'],['kosten','Preisvergleich'],['shop','Gewürzshop'],['premium','Premium'],['refill','Nachfüllen'],['dosen','Gläser & Etiketten'],['warenkorb','Testkorb']].map(([p,t])=>`<button data-nav="${p}" aria-current="${s.page===p?'page':'false'}">${t}</button>`).join('')}</nav></header>`;}
function recipeCard(r){const have=r.ingredients.filter(p=>s.pantry.has(p.ingredient)).length,n=r.ingredients.length;return `<article class="mk-card recipe"><div><span class="mk-badge">${esc(r.kind)}</span> <span class="mk-muted">${r.countries.map(flag).join(' ')}</span></div><div class="mk-photo-row">${r.ingredients.slice(0,3).map(p=>photo(p.ingredient)).join('')}</div><h3>${esc(r.name)}</h3><a class="mk-link" href="/mischung/${encodeURIComponent(r.id)}/">Öffentliche Rezeptseite →</a><p>${esc(r.description)}</p><small class="mk-muted">${esc(editorialLabel(r))} · ${n} Zutaten</small><div class="mk-progress" aria-hidden="true"><span style="width:${n?have/n*100:0}%"></span></div><small class="mk-muted">${have} von ${n} Zutaten in deinem Regal</small><div class="mk-card-bottom">${button('Ansehen →','recipe',r.id,'soft')}<button class="mk-link" data-action="favorite" data-id="${esc(r.id)}" aria-label="${esc(r.name)} merken" aria-pressed="${s.favorites.has(r.id)}">${s.favorites.has(r.id)?'♥ Gemerkt':'♡ Merken'}</button></div></article>`;}
function home(){return `<section class="mk-hero"><div class="mk-hero-copy"><div class="mk-eyebrow">Deine Entdeckungsreise durch die Küchen der Welt.</div><h1>Mein Kraut.<br><em>Dein Geschmack.</em></h1><p class="mk-slogan" lang="en">My Spice. Your Taste.</p><p>Entdecke die Küchen der Welt und ihre Gewürze. Reise von Land zu Land, finde neue Lieblingsaromen und mische deinen eigenen Steakpfeffer, BBQ-Rub oder deine Lieblingskräuter – mit genauen Mengen und ganz nach deinem Geschmack.</p><div class="mk-actions">${nav('Auf Entdeckungsreise gehen →','laender','primary')}${nav('Selbst mischen','rezepte')}</div><p class="mk-muted">Rezept wählen. Abwiegen. Mischen. Beschriften. Ohne Vorkenntnisse starten – aktuell kostenlos und ohne Registrierung.</p></div><img class="mk-hero-logo" src="${logo}" alt="Mein Kraut – dein Geschmack: grauer Steinmörser mit Pfeffer, Kräutern, Sternanis und Zimt" width="470" height="470" fetchpriority="high"></section>${savingsTeaser()}${occasions()}<div class="mk-stats"><div><b>${db.ingredients.length}</b><span>Zutaten im Weltregal</span></div><div><b>${recipes.length}</b><span>Rezepturen & Würzideen</span></div><div><b>${db.countries.length}</b><span>Länder entdecken</span></div><div><b>${Object.keys(extra.countries||{}).length}</b><span>vertiefte Länderporträts</span></div></div><div class="mk-grid">${[['01','Aussuchen','Wähle eine Mischung oder ein Land. Du siehst jede Zutat und wofür sie gut ist.','rezepte'],['02','Selbst mischen','Mit Digitalwaage genau abwiegen oder Löffel-Richtwerte nutzen. Würze nach deinem Geschmack.','werkstatt'],['03','Dein Glas. Dein Etikett.','Mischung speichern, beschriften und beim nächsten Mal genauso wieder herstellen.','dosen']].map(([n,t,p,v])=>`<article class="mk-card"><span class="mk-step-number">${n}</span><h3>${t}</h3><p>${p}</p>${nav('Los geht’s →',v,'soft')}</article>`).join('')}</div><section class="mk-section"><div class="mk-section-head"><div><div class="mk-eyebrow">Kleine Mischung. Großer Anfang.</div><h2>Damit fängt dein Regal an.</h2></div>${nav('Alle Mischungen →','rezepte')}</div><div class="mk-grid">${recipes.filter(r=>r.id.startsWith('mk-')).slice(0,6).map(recipeCard).join('')}</div></section><section class="mk-card"><div class="mk-eyebrow">Selbst machen statt fertig kaufen</div><h2>Dein Geschmack gehört dir.<br>Deine Rezeptur auch.</h2><p>Aus einzelnen Gewürzen werden immer neue Lieblingsmischungen. Passe Salz, Schärfe und Kräuter an – und vergleiche transparent, was deine verbrauchten Zutaten kosten.</p>${nav('Kostenbeispiel ansehen →','kosten','primary')}<p class="mk-muted mk-spacer">Die Rezepturen sind eigene Hausvarianten. Eine Zutatenliste veröffentlicht nicht automatisch die Originalmengen eines Herstellers.</p></section><section class="mk-section"><h2>Dein Gewürzregal wächst mit dir.</h2><p class="mk-lead">Einsteiger beginnen mit kleinen Mengen. Wer viel kocht, kann größere Nachfüllpackungen vergleichen. Mein Kraut verbindet Rezepte, Wissen, Vorrat und Beschriftung – damit aus wenigen Grundzutaten viele eigene Mischungen werden. Dein dunkles Glas mit Deckel und personalisiertem Etikett hat einen Zielpreis von 2,99 €. Später ergänzen BASIC-Nachfüllpackungen und ausgesuchte Premiumgewürze dein Regal.</p><div class="mk-actions">${nav('Mein Regal einrichten','regal','primary')}${nav('Dein Glas & Etikett gestalten','dosen')}${nav('Grundgewürze nachfüllen','shop')}</div></section>`;}
function paginate(items,renderItem){const size=24,max=Math.max(1,Math.ceil(items.length/size));s.pageNo=Math.min(s.pageNo,max);return `<p class="mk-muted">${items.length} Treffer · Seite ${s.pageNo} von ${max}</p><div class="mk-grid">${items.slice((s.pageNo-1)*size,s.pageNo*size).map(renderItem).join('')}</div>${items.length===0?'<div class="mk-empty">Keine Treffer. Ändere deine Suche oder die Filter.</div>':''}${max>1?`<div class="mk-pagination"><button class="mk-btn" data-action="prev" ${s.pageNo===1?'disabled':''}>← Zurück</button><span>${s.pageNo} / ${max}</span><button class="mk-btn" data-action="next" ${s.pageNo===max?'disabled':''}>Weiter →</button></div>`:''}`;}
function recipeList(){const items=recipes.filter(r=>(s.kind==='Alle'||r.kind===s.kind)&&(s.country==='Alle'||r.countries.includes(s.country))&&(!s.ownedOnly||r.ingredients.every(p=>s.pantry.has(p.ingredient)))&&norm(r.name+' '+r.description+' '+r.countries.map(c=>countryMap.get(c)?.name).join(' ')+' '+r.ingredients.map(p=>name(p.ingredient)).join(' ')).includes(norm(s.search)));return title('Deine Rezeptwerkstatt','Welcher Geschmack darf’s sein?','Starte mit einer kleinen Trockenmischung. Grammrezepturen lassen sich frei anpassen. Andere Ansätze behalten die belegten Originaleinheiten.')+`<div class="mk-toolrow">${search('Steakpfeffer, Bolognese, Masala …')}<select data-field="kind" aria-label="Rezeptart">${['Alle',...new Set(recipes.map(r=>r.kind))].map(k=>`<option ${s.kind===k?'selected':''}>${esc(k)}</option>`).join('')}</select><select data-field="country" aria-label="Land"><option value="Alle">Alle Länder</option>${db.countries.map(c=>`<option value="${c.code}" ${s.country===c.code?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label class="mk-inline-check"><input type="checkbox" data-field="ownedOnly" ${s.ownedOnly?'checked':''}>Mit meinem Vorrat machbar</label></div><div class="mk-pills"><button data-action="starter" aria-pressed="${s.kind==='Trockenmischung'}">Trockenmischungen</button><button data-action="all-recipes">Alle Rezeptarten</button>${button('Eigene Mischung beginnen','blank')}</div>${paginate(items,recipeCard)}<p class="mk-muted mk-spacer">Die Sammlung enthält redaktionelle Haushaltsvarianten, keine vollständige Sammlung geprüfter Nationalrezepte. Neue Rezepturen sind noch nicht verkostet. Bilder sind Symbolbilder und teils mehreren Zutaten zugeordnet.</p>`;}
function knowledgeDetails(i){const k=extra.ingredients?.[i.id];if(!k)return `<p><b>Verwendung:</b> ${esc(i.usage)}</p><p><b>Lagerung:</b> ${esc(i.storage)}</p><p class="mk-muted">Dieses vertiefte Gewürzporträt wird noch ergänzt.</p>`;const fields=[['botanicalName','Botanischer Name'],['origin','Ursprung'],['currentCultivation','Heutige Anbaugebiete'],['cultivation','Anbau'],['plantPart','Verwendeter Pflanzenteil'],['harvestProcessing','Ernte & Verarbeitung'],['preparation','So verarbeitest du es'],['pairing','Passt dazu'],['storage','Aufbewahrung'],['buyingAdvice','Einkauf'],['healthEvidence','Inhaltsstoffe & Wissensstand'],['timingNote','Zeitangaben']];return fields.filter(([key])=>k[key]).map(([key,t])=>`<h4>${t}</h4><p>${esc(Array.isArray(k[key])?k[key].join(' '):k[key])}</p>`).join('')+`<details><summary>Quellen zum Gewürzporträt</summary><ul class="mk-source">${sourceLinks(k.sources)}</ul></details>`;}
function ingredientCard(i){return `<article class="mk-card"><div class="mk-ingredient-head">${photo(i)}<div><h3>${esc(i.name)}</h3><small class="mk-muted">${esc(i.form)} · ${esc(i.subcategory)}</small></div><button class="mk-btn ${s.pantry.has(i.id)?'primary':''}" data-action="pantry" data-id="${i.id}" aria-label="${esc(i.name)} ${s.pantry.has(i.id)?'aus Vorrat entfernen':'zum Vorrat hinzufügen'}" aria-pressed="${s.pantry.has(i.id)}">${s.pantry.has(i.id)?'✓':'+'}</button></div><p>${esc(i.flavor||i.usage)}</p><details><summary>Herkunft, Verwendung & Lagerung</summary>${knowledgeDetails(i)}${i.allergens?.length?`<p><b>Enthaltene Allergene:</b> ${esc(i.allergens.join(', '))}</p>`:''}${i.alternatives?`<p><b>Ersatzidee:</b> ${esc(i.alternatives)}</p>`:''}</details><button class="mk-link" data-action="ingredient-recipes" data-id="${i.id}">Mischungen mit ${esc(i.name)} →</button></article>`;}
function pantry(){const items=db.ingredients.filter(i=>(s.group==='Alle'||i.group===s.group)&&(!s.ownedOnly||s.pantry.has(i.id))&&norm(i.name+' '+i.flavor+' '+i.subcategory).includes(norm(s.search)));return title('Dein persönlicher Vorrat','Was steht schon im Regal?','Markiere deine Zutaten mit +. Mein Kraut zeigt dir dann passende Mischungen und sammelt fehlende Zutaten auf deiner Einkaufsliste.')+`<div class="mk-toolrow">${search('Gewürze und Grundzutaten suchen …')}<select data-field="group" aria-label="Zutatengruppe">${['Alle',...new Set(db.ingredients.map(i=>i.group))].map(g=>`<option ${s.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select><label class="mk-inline-check"><input type="checkbox" data-field="ownedOnly" ${s.ownedOnly?'checked':''}>Nur mein Vorrat (${s.pantry.size})</label></div><div class="mk-actions">${nav('Grammvorrat & Nachfüllen','refill')}${nav('Einkaufsliste ('+s.basket.size+')','einkauf')}${nav('Meine Mischungen ('+s.saved.length+')','meine')}${button('Regal exportieren','export')}${button('Regal importieren','import')}</div><p class="mk-muted">Dein Regal und deine Mischungen bleiben in diesem Browser. Mit Export sicherst du sie oder nimmst sie auf ein anderes Gerät mit.</p>${paginate(items,ingredientCard)}`;}
const countryAliases={DE:'deutsch deutsche deutschland',IT:'italienisch italienische',FR:'französisch französische',CN:'chinesisch chinesische',TR:'türkisch türkische',BR:'brasilianisch brasilianische',JP:'japanisch japanische',TH:'thailändisch thailändische thai',IN:'indisch indische',VN:'vietnamesisch vietnamesische',KR:'koreanisch koreanische südkorea',MX:'mexikanisch mexikanische',GR:'griechisch griechische',ES:'spanisch spanische',US:'amerikanisch amerikanische usa',MA:'marokkanisch marokkanische',GE:'georgisch georgische',IR:'persisch iranisch',AR:'argentinisch argentinische',ZA:'südafrikanisch',EG:'ägyptisch',ET:'äthiopisch',LB:'libanesisch',ID:'indonesisch'};
function countries(){const c=countryMap.get(s.countryCode)||db.countries[0],p=extra.countries?.[c.code],hits=recipes.filter(r=>r.countries.includes(c.code)),ids=(p?.typicalSpices||c.pantry||[]).filter(id=>ingredients.has(id)),listed=db.countries.filter(x=>(s.continent==='Alle'||x.region===s.continent)&&norm(x.name+' '+(countryAliases[x.code]||'')).includes(norm(s.search)));return title('Die Welt hat viele Küchen','Wohin geht deine Gewürzreise?','Entdecke, was in einem Land gegessen wird, welche Gewürze eine Rolle spielen und wie du mit einer ersten eigenen Mischung einsteigst.')+`<div class="mk-actions">${nav(db.regions.length+' kulinarische Regionen entdecken →','regionen','soft')}</div><div class="mk-toolrow">${search('Land oder Küche: China, italienisch …')}<select data-field="continent" aria-label="Kontinent">${['Alle','Europa','Asien','Afrika','Amerika','Ozeanien'].map(x=>`<option ${s.continent===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="mk-countries"><nav class="mk-countrylist" aria-label="Länder auswählen">${listed.map(x=>`<button data-action="country" data-id="${x.code}" aria-current="${c.code===x.code}"><span>${flag(x.code)} ${esc(x.name)}</span><small>${extra.countries?.[x.code]?'Porträt':'Regal'}</small></button>`).join('')}</nav><article class="mk-countrydetail"><div class="mk-eyebrow">${esc(c.region)} · ${hits.length} Würzideen</div><h2>${flag(c.code)} ${esc(c.name)}</h2>${p?`<p>${esc(p.intro)}</p><h3>Was kommt auf den Tisch?</h3><div class="mk-grid two">${p.typicalDishes.map(d=>`<div class="mk-card"><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p></div>`).join('')}</div>`:`<p>${esc(c.flavorNote)}</p><div class="mk-note">Das ausführliche Länderporträt mit Gerichten und Zubereitungstechniken ist noch in Arbeit. Das zugeordnete Gewürzregal und die Rezeptideen kannst du bereits erkunden.</div>`}<h3 class="mk-spacer">Ein Einstieg ins Gewürzregal</h3><div class="mk-photo-row">${ids.map(id=>`<button data-action="ingredient" data-id="${id}">${photo(id)}<span>${esc(name(id))}</span></button>`).join('')}</div>${p?`<h3>So wird gekocht</h3><ul>${p.techniques.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Deine ersten Schritte</h3><ol>${p.firstSteps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><details><summary>Quellen & Einordnung</summary><p class="mk-muted">${esc(p.status)}. Die Auswahl zeigt einen Einstieg in vielfältige regionale Küchen.</p><ul class="mk-source">${sourceLinks(p.sources)}</ul></details>`:''}<h3 class="mk-spacer">Passende Mischungen & Würzideen</h3>${hits.slice(0,16).map(r=>`<div class="mk-list-row"><span>${esc(r.name)}</span>${button('Öffnen','recipe',r.id)}</div>`).join('')}${hits.length>16?button('Alle '+hits.length+' Rezepturen ansehen','country-recipes',c.code):''}</article></div>`;}
function regions(){const r=db.regions.find(x=>x.id===s.regionId)||db.regions[0],hits=(r.recipeIds||[]).map(id=>recipeMap.get(id)).filter(Boolean),listed=db.regions.filter(x=>norm(x.name+' '+x.scope+' '+x.continent).includes(norm(s.search)));return title('Kulinarische Regionen','Geschmack kennt viele Grenzen.','Entdecke zusätzliche kulinarische Einträge und Regionen. Die Zuordnungen dienen der Orientierung; sie legen keine einheitliche Nationalküche fest.')+`<div class="mk-actions">${nav('← Zur Länderauswahl','laender')}</div><div class="mk-toolrow">${search('Taiwan, Sichuan, Kreta, Punjab …')}</div><div class="mk-countries"><nav class="mk-countrylist" aria-label="Regionen auswählen">${listed.map(x=>`<button data-action="region" data-id="${esc(x.id)}" aria-current="${r.id===x.id}"><span>${esc(x.name)}</span><small>${(x.recipeIds||[]).length} Rezepte</small></button>`).join('')}</nav><article class="mk-countrydetail"><div class="mk-eyebrow">${esc(r.continent)} · ${esc(r.entryType)}</div><h2>${esc(r.name)}</h2><p>${esc(r.scope)}</p><p class="mk-muted">Ein praktischer Einstieg mit redaktionellen Hausvarianten. Die regionale Vielfalt geht über diese Auswahl hinaus.</p><div class="mk-photo-row">${(r.pantry||[]).filter(id=>ingredients.has(id)).map(id=>`<button data-action="ingredient" data-id="${id}">${photo(id)}<span>${esc(name(id))}</span></button>`).join('')}</div><h3>Passende Rezepturen</h3>${hits.map(x=>`<div class="mk-list-row"><span>${esc(x.name)}</span>${button('Öffnen','recipe',x.id)}</div>`).join('')}</article></div>`;}
function partsFromRecipe(r){return r.ingredients.map(p=>{let g=p.unit==='g'?p.amount:p.unit==='TL'&&conversion(p.ingredient)?p.amount*conversion(p.ingredient):p.unit==='EL'&&conversion(p.ingredient)?p.amount*conversion(p.ingredient)*3:null;return {id:p.ingredient,grams:g,enabled:true};});}
function canMix(r){return r.kind==='Trockenmischung'&&partsFromRecipe(r).every(p=>p.grams!==null);}
function startMix(r){if(!canMix(r)){toast('Für diese Rezeptur bleiben die ursprünglichen Einheiten erhalten. Eine eigene Mischung kannst du in Gramm neu anlegen.');return;}s.workRecipe=r;s.parts=partsFromRecipe(r);s.customName=r.name;window.MEINKRAUT_COMMERCE?.syncLabelName(s.customName);s.target=100;s.checked.clear();s.modal='';navigate('werkstatt',false);}
function currentRows(){const total=s.parts.filter(p=>p.enabled).reduce((a,p)=>a+p.grams,0);return s.parts.map(p=>({...p,amount:p.enabled&&total>0?p.grams/total*s.target:0,percent:p.enabled&&total>0?p.grams/total*100:0}));}
function amountString(row){if(s.unit==='g')return number(row.amount)+' g';const d=conversion(row.id);return d?'≈ '+number(row.amount/d/(s.unit==='EL'?3:1))+' '+s.unit:'keine Löffelschätzung';}
function workTable(){return `<table><thead><tr><th>Zutat verwenden</th><th>Gewichtung in g</th><th>Anteil</th><th>Abwiegen${s.unit!=='g'?' / Schätzung':''}</th></tr></thead><tbody>${currentRows().map((p,n)=>`<tr><td><label class="mk-included"><input type="checkbox" data-part-toggle="${n}" ${p.enabled?'checked':''}>${photo(p.id,'tiny')}<span>${esc(name(p.id))}</span></label></td><td><input type="number" min="0" max="10000" step="0.1" value="${p.grams}" data-part-grams="${n}" aria-label="Gewichtung ${esc(name(p.id))}"></td><td class="mk-number">${number(p.percent,1)} %</td><td class="mk-number"><strong>${amountString(p)}</strong></td></tr>`).join('')}</tbody></table>`;}
function workshop(){if(!s.parts.length)return title('Deine Mischküche','Aus Gewürzen wird dein Geschmack.','Beginne mit einer vorbereiteten Mischung oder stelle deine eigene Rezeptur aus Grundzutaten zusammen.')+`<div class="mk-actions">${nav('Mischung auswählen','rezepte','primary')}${button('Leere Rezeptur starten','blank')}</div><div class="mk-grid">${(extra.mixes||[]).slice(0,3).map(recipeCard).join('')}</div>`;const rows=currentRows(),steps=s.workRecipe?.methodSteps||['Gewürze nach Bedarf mahlen oder mörsern. Für einen trockenen Vorrat ausschließlich vollständig getrocknete Zutaten verwenden.','Die berechneten Mengen einzeln abwiegen und gründlich vermischen.','Eine kleine Menge im vorgesehenen Gericht probieren und deine Rezeptur bei Bedarf anpassen.','In eine saubere, vollständig trockene Dose füllen. Beschriften und trocken, kühl und lichtgeschützt aufbewahren.'];return title('Deine Mischküche','Genau dein Geschmack.','Verändere die Gewichtung oder lasse Zutaten weg. Mein Kraut verteilt die gewünschte Gesamtmenge automatisch auf die aktiven Zutaten.')+`<div class="mk-workshop"><section class="mk-card"><label class="mk-field">Name deiner Mischung<input class="mk-recipe-title" maxlength="100" data-field="customName" value="${esc(s.customName)}"></label><div class="mk-work-controls"><label class="mk-field">${s.workRecipe?.massBasis==='Einwaage vor dem Rösten'?'Einwaage':'Gesamtmenge'}<input type="number" min="1" max="5000" step="1" data-field="target" value="${s.target}"></label><span>Gramm</span><label class="mk-field">Anzeige<select data-field="unit">${['g','TL','EL'].map(u=>`<option ${s.unit===u?'selected':''}>${u}</option>`).join('')}</select></label>${[50,100,200].map(n=>button(n+' g','target',String(n),'soft')).join('')}</div><div class="mk-table-wrap" id="mk-work-table">${workTable()}</div><p class="mk-muted">Die Gewichtung ist dein Mischungsverhältnis. Daraus berechnet sich die Abwiegemenge. Nur aktive Zutaten zählen zur Gesamtmenge.</p>${s.unit!=='g'?'<div class="mk-note">TL und EL sind ungefähre, gestrichene Löffelmengen. Mahlgrad, Verdichtung und Löffelgröße verändern das Gewicht. Für eine wiederholbare Rezeptur nimm eine Digitalwaage; bei sehr kleinen Mengen eine Feinwaage.</div>':''}<div class="mk-toolrow"><select id="mk-add-ingredient" aria-label="Zutat ergänzen"><option value="">Weitere Zutat auswählen</option>${db.ingredients.filter(i=>dryIngredient(i)&&!s.parts.some(p=>p.id===i.id)).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select>${button('Hinzufügen','add-part')}</div><div class="mk-actions">${button('Eigene Mischung speichern','save-mix','','primary')}${button('Fehlendes auf Einkaufsliste','missing-work')}<button class="mk-btn" data-action="mix-refill">Zutaten nachfüllen →</button>${button('Neue leere Mischung','blank')}</div><p class="mk-muted">${esc(s.workRecipe?editorialLabel(s.workRecipe):'Deine eigene Rezeptur')}. ${esc(s.workRecipe?.reviewStatus||'Geschmack selbst erproben.')}</p>${recipeNotes(s.workRecipe)}${recipeSources(s.workRecipe)}<h3>Schritt für Schritt</h3>${steps.map((t,n)=>`<label class="mk-tick-step"><input type="checkbox" data-step="${n}" ${s.checked.has(n)?'checked':''}><span>${n+1}. ${esc(t.replace('Die Rezeptur ergibt 100 g.','Dein Ansatz ergibt '+number(s.target)+' g.'))}</span></label>`).join('')}${s.workRecipe?.adjustments?.length?`<h4>So kannst du variieren</h4><p class="mk-muted">Die Variantenideen beziehen sich auf 100 g Grundrezept.</p><ul>${s.workRecipe.adjustments.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}</section><aside><section class="mk-card"><div class="mk-eyebrow">Deine Dose wird persönlich</div><div class="mk-label-preview"><img src="${logo}" alt="Mein Kraut Logo"><strong id="mk-label-name">${esc(s.customName)}</strong><small id="mk-label-weight">${number(rows.reduce((a,p)=>a+p.amount,0))} g · ${esc(s.labelDate)}</small></div><button class="mk-btn primary" data-shop-action="labels">Persönliches Etikett gestalten →</button>${button('Rezept & Mengen drucken','print-work')}<p class="mk-muted mk-spacer">Dein persönliches Dekoretikett gestaltest du im Etikettenatelier. Rezept und Mengen bleiben separat druckbar; Pflichtangaben verkaufter Lebensmittel dürfen nicht überklebt werden.</p></section><div class="mk-note"><b>Deine Kontrolle über die Zutaten</b><p>Du kannst eine Zutat entfernen und passende Alternativen testen. Prüfe bei Unverträglichkeiten auch die Einzelprodukte und mögliche Spuren.</p></div><section class="mk-card"><h3>Das brauchst du</h3><p>Digitalwaage, kleine Schüssel, sauberer Löffel und eine trockene Dose. Für ganze Gewürze ergänzen Mörser oder Gewürzmühle deinen Werkzeugkasten.</p>${nav('Dosen & Beschriftung →','dosen')}</section></aside></div>`;}
function knowledge(){const items=db.ingredients.filter(i=>extra.ingredients?.[i.id]&&norm(i.name).includes(norm(s.search)));return title('Wissen macht den Unterschied','Vom Anbau bis in deine Dose.','Erfahre, wo Gewürze herkommen, welcher Pflanzenteil verwendet wird und wie du Aroma durch Verarbeitung und Lagerung erhältst.')+`<div class="mk-grid"><article class="mk-card"><h3>Ganz oder gemahlen?</h3><p>Ganze Gewürze portionsweise mit Mörser oder Gewürzmühle zerkleinern. Für sehr kleine Mengen arbeitet ein großer Küchenmixer oft weniger gleichmäßig. Kräuter lassen sich zwischen den Fingern verreiben.</p></article><article class="mk-card"><h3>Trocken. Kühl. Dunkel.</h3><p>Luftdicht schließende, lichtundurchlässige Behälter verwenden. Dosen nicht über dem Herd lagern oder direkt über dampfenden Töpfen öffnen. Nur kleine Arbeitsmengen abfüllen.</p></article><article class="mk-card"><h3>Passend einkaufen</h3><p>500 Gramm können bei häufig verwendeten Gewürzen sinnvoll sein. Bei Kräutern, Chili und seltenen Zutaten sind kleinere Mengen oft praktischer. Gemahlene Gewürze für guten Aromaerhalt möglichst binnen eines Jahres nach dem Öffnen verbrauchen.</p></article></div><p class="mk-source">Grundlagen: <a href="https://www.bzfe.de/presse/pressemeldungen-archiv/gewuerze-und-kraeuter-sicher-geniessen" target="_blank" rel="noopener noreferrer">Bundeszentrum für Ernährung – Einkauf & Lagerung</a></p><div class="mk-toolrow">${search('Gewürzporträt suchen …')}</div>${paginate(items,ingredientCard)}<div class="mk-note">Informationen zu Inhaltsstoffen unterscheiden traditionelle Verwendung und belastbare Erkenntnisse. Gewürze sind Lebensmittel; die hier beschriebenen Küchenmengen sind keine medizinische Behandlung.</div>`;}
function kit(){return window.MEINKRAUT_COMMERCE?.renderPage('dosen')||legacyKit();}
function legacyKit(){return title('Dein Geschmack. Dein ganzes Gewürzregal.','Grundgewürze. Gläser. Deine Rezepturen.','Mein Kraut macht aus einzelnen Gewürzen deine eigenen Lieblingsmischungen. Dazu entsteht unser Shop für Grundgewürze, passende Gläser und persönliche Beschriftung.')+`<div class="mk-grid"><article class="mk-card"><span class="mk-step-number">01</span><div class="mk-eyebrow">Shop in Vorbereitung</div><h3>Die Grundgewürze</h3><p>Pfeffer, Paprika, Kräuter und mehr: Künftig kannst du die einzelnen Gewürze direkt bei Mein Kraut bestellen und nach Bedarf nachfüllen. Aus deinem Vorrat entstehen immer neue Mischungen.</p><p>Wähle die Packungsgröße passend zu deinem Verbrauch. Auch größere Nachfüllpackungen sind geplant.</p>${nav('Deinen Vorrat planen →','regal','primary')}</article><article class="mk-card"><span class="mk-step-number">02</span><div class="mk-eyebrow">Sortiment in Vorbereitung</div><h3>Deine Gewürzgläser</h3><p>Geplant sind schwarze Gläser mit passenden Deckeln und einheitlicher Beschriftung. Bei der Auswahl zählen Lebensmitteleignung, Lichtschutz und ein dichter Verschluss.</p><p>Als Kandidat prüfen wir ein schwarzes 192-ml-Schraubglas. Wie viel Gramm hineinpassen, hängt vom Gewürz und Mahlgrad ab. Glas und Deckel werden vor dem Verkaufsstart gemeinsam geprüft.</p></article><article class="mk-card"><span class="mk-step-number">03</span><div class="mk-eyebrow">Jetzt kostenlos testen</div><h3>Dein Zugang zum Wissen</h3><p>Rezepturen, Länderwissen und Mengenrechner zeigen dir Schritt für Schritt, wie du selbst mischst und deinen Geschmack veränderst. Später wird der Datenbankzugang ein kostenpflichtiges Angebot.</p><p>Während der Testphase ist die Datenbank kostenlos und ohne Registrierung zugänglich.</p>${nav('Mischungen ausprobieren →','rezepte','primary')}</article></div><section class="mk-section mk-card"><div class="mk-eyebrow">Dein Regal bekommt deinen Namen</div><h2>Die passende Beschriftung gehört dazu.</h2><p>Für das Beschriftungssystem arbeitet Oliver mit einer Agentur zusammen. Gläser und auf Wunsch gedruckte Etiketten sollen deine eigenen Mischungen zu einem übersichtlichen Gewürzregal machen.</p><p>Schon jetzt kannst du Name, Zutaten, Grammangaben und Mischdatum aus der Mischküche ausdrucken. Für Gläser und professionelle Beschriftung kannst du deinen Bedarf anfragen; Ausführung und Preis stimmen wir vor einer Bestellung ab.</p><div class="mk-actions">${nav('Eigenes Etikett erstellen','werkstatt','primary')}<a class="mk-btn" href="https://odpc.de/?page_id=535">Gläser & Beschriftung anfragen →</a></div></section><section class="mk-section mk-card"><h2>Selbst mischen. Gezielt nachfüllen.</h2><p>Du bestimmst Salz, Schärfe und Kräuter selbst. Vergleiche den Verbrauch deiner Grundgewürze mit einer fertigen Mischung. Für deine gesamte Ersparnis zählen auch Gläser, Etiketten, Versand und später der Datenbankzugang.</p>${nav('Transparentes Kostenbeispiel →','kosten')}</section><div class="mk-note"><b>So bleibt dein Vorrat gut aufbewahrt.</b><p>Glas, Deckel, Löffel und Zutaten müssen sauber und vollständig trocken sein. Bewahre trockene Mischungen gut verschlossen, kühl und lichtgeschützt auf. Frische Zutaten und Öl gehören nicht in einen trockenen Vorratsmix.</p></div>`;}
function costs(){const cost=priceRows.reduce((a,[,g,p])=>a+g*p/500,0);return title('Was steckt hinter dem Preis?','Selber mischen. Ehrlich vergleichen.','Ein konkretes Rechenbeispiel mit veröffentlichten Einkaufspreisen – damit du selbst entscheiden kannst, wann sich das eigene Gewürzregal lohnt.')+`<section class="mk-card"><h2>Italienische Kräuter im Vergleich</h2><p>Vergleichsprodukt: Ankerkraut „Italienische Kräuter“, 25 g im Korkenglas für 5,49 €. Eigene Beispielrezeptur mit denselben sechs Kräuterarten und frei gewählten Mengen. Der Geschmack wurde noch nicht vergleichend verkostet.</p><div class="mk-price-compare"><div><small>Ankerkraut · 25 g im Glas</small><b>5,49 €</b><small>21,96 € je 100 g</small></div><div><small>Eigene Rezeptur · Zutaten für 25 g</small><b>${euro(cost/4)}</b><small>${euro(cost)} je 100 g</small></div></div><p><strong>${euro(5.49-cost/4)} Differenz pro 25 g – rechnerisch rund ${number((1-cost/4/5.49)*100,0)} % im Beispiel.</strong> Verglichen werden eigene Zutatenkosten mit dem fertigen Markenglas. Versand, eigene Behälter, Etiketten, Arbeitszeit, ungenutzte Vorräte und ein späterer Datenbankzugang sind in dieser Prozentzahl nicht enthalten. Mit dem geplanten 2,99-€-Glas einschließlich Deckel und Standardetikett läge der erste 25-g-Ansatz bei rund 3,26 € zuzüglich Versand; ein späterer App-Zugang käme gesondert hinzu. Das Glas kannst du danach wiederverwenden. Das ist kein allgemeines Sparversprechen und keine Kalkulation der internen Herstellungskosten von Ankerkraut.</p><div class="mk-table-wrap"><table><thead><tr><th>Zutat</th><th>Rezeptmenge</th><th>500-g-Packung</th><th>Verbrauchskosten</th></tr></thead><tbody>${priceRows.map(([n,g,p,u])=>`<tr><td><a href="${u}" target="_blank" rel="noopener noreferrer">${n}</a></td><td>${g} g</td><td>${euro(p)}</td><td>${euro(g*p/500)}</td></tr>`).join('')}</tbody></table></div><div class="mk-note">Der erste Einkauf dieser sechs 500-g-Packungen kostet <b>${euro(priceRows.reduce((sum,[,,p])=>sum+p,0))}</b> für insgesamt 3 kg Kräuter, zuzüglich Versand. Das ist deutlich mehr als die Kosten eines einzelnen Glases und für viele Haushalte zu viel Vorrat. Die Rechnung setzt voraus, dass du die Zutaten auch verbrauchst.</div><p class="mk-muted">Preisrecherche: 21.10.2026, inkl. Mehrwertsteuer, ohne Versand. Preise und Packungsgrößen können sich ändern. Kleine Markenpackung und größere Nachfüllpackungen haben unterschiedliche Verpackungs- und Vertriebsanteile.</p><p class="mk-source"><a href="https://www.ankerkraut.de/products/italienische-kraeuter" target="_blank" rel="noopener noreferrer">Vergleichsprodukt und Zutatenliste bei Ankerkraut</a></p>${button('Beispiel in Mischküche öffnen','price-mix','','primary')}</section>`;}
function savedMixes(){return title('Deine Rezepturen','So schmeckt dein Regal.','Hier liegen deine persönlichen Mischungen. Sie werden lokal in diesem Browser gespeichert. Nutze Export für eine eigene Sicherung.')+`<div class="mk-actions">${button('Regal exportieren','export')}${button('Regal importieren','import')}${button('Neue Mischung','blank','','primary')}</div>${s.saved.length?`<div class="mk-grid">${s.saved.map(r=>`<article class="mk-card mk-saved-card"><div class="mk-photo-row">${r.parts.slice(0,3).map(p=>photo(p.id)).join('')}</div><h3>${esc(r.name)}</h3><p>${r.parts.filter(p=>p.enabled!==false).length} Zutaten · ${number(r.target)} g</p><small class="mk-muted">Gespeichert ${esc(r.date)}</small><div class="mk-actions">${button('Bearbeiten','load-mix',r.id,'primary')}${button('Zutaten nachfüllen','saved-refill',r.id)}${button('Entfernen','delete-mix',r.id)}</div></article>`).join('')}</div>`:'<div class="mk-empty">Noch keine eigene Mischung gespeichert. Öffne eine Rezeptur in der Mischküche und speichere deine Variante.</div>'}`;}
function shopping(){return title('Für dein nächstes Küchenabenteuer','Deine Einkaufsliste.','Hier sammelst du fehlende Zutaten. Kaufe Größen, die du in deiner Küche tatsächlich verbrauchst.')+`<div class="mk-actions">${button('Liste kopieren','copy-shopping')}${button('Liste drucken','print-shopping')}${button('Regal exportieren','export')}</div>${s.basket.size?[...s.basket].map(id=>`<div class="mk-list-row"><span>${photo(id,'tiny')}${esc(name(id))}</span><div>${button('Jetzt im Vorrat','pantry',id)} ${button('Entfernen','remove-basket',id)}</div></div>`).join(''):'<div class="mk-empty">Deine Einkaufsliste ist leer. Ergänze fehlende Zutaten aus einer Rezeptur.</div>'}`;}
function footer(){return `<footer class="mk-footer"><div><img class="mk-footer-logo" src="${base}assets/mein-kraut-logo-192.webp?v=final-1" alt="Mein Kraut – Gewürze selbst mischen" width="104" height="104" loading="lazy"><b>Mein Kraut. Dein Geschmack.</b><p class="mk-slogan" lang="en">My Spice. Your Taste.</p><p>Dein weltweites Gewürzregal. Eigene Mischungen verstehen, ausprobieren und wieder herstellen.</p><span>Kostenlose Testphase · 3.0 Testshop</span></div><div><p>${nav('Meine Mischungen','meine','soft')} ${nav('Einkaufsliste','einkauf','soft')}</p><a href="https://odpc.de/impressum/">Impressum</a> · <a href="https://odpc.de/datenschutzerklaerung/">Datenschutz</a> · <a href="https://odpc.de/?page_id=535">Feedback & Kontakt</a><p class="mk-muted" style="color:#c6ddce">Dein Regal speichert lokal. Eine Serversicherung ist nur im freiwilligen Testkonto möglich.<br>powered by <a href="https://odpc.de/">odpc.de</a></p></div></footer>`;}
let dialogOpener=null;
function modal(){if(!s.modal)return '';if(s.modal.startsWith('ingredient:')){const i=ingredients.get(s.modal.slice(11));if(!i)return '';return dialog(`<div class="mk-ingredient-head">${photo(i,'large')}<div><div class="mk-eyebrow">Dein Gewürzporträt</div><h2>${esc(i.name)}</h2></div></div>${knowledgeDetails(i)}<div class="mk-actions">${button(s.pantry.has(i.id)?'Im Vorrat ✓':'Zum Vorrat hinzufügen','pantry',i.id,'primary')}${button('Passende Rezepte','ingredient-recipes',i.id)}</div>`);}
const r=recipeMap.get(s.modal);if(!r)return '';return dialog(`<div class="mk-eyebrow">${esc(r.kind)} · ${r.countries.map(flag).join(' ')}</div><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><span class="mk-badge">${esc(editorialLabel(r))}</span><div class="mk-toolrow"><label class="mk-field">Rezeptansatz<select data-field="recipeFactor">${[.25,.5,1,2,3,5].map(v=>`<option value="${v}" ${s.recipeFactor===v?'selected':''}>${number(v)} ×</option>`).join('')}</select></label></div><div class="mk-table-wrap"><table><thead><tr><th>Zutat</th><th>Menge</th><th>Im Regal</th></tr></thead><tbody>${r.ingredients.map(p=>`<tr><td>${photo(p.ingredient,'tiny')}${esc(name(p.ingredient))}</td><td>${number(p.amount*s.recipeFactor)} ${esc(p.unit)}</td><td><button class="mk-btn" data-action="pantry" data-id="${p.ingredient}" aria-label="${esc(name(p.ingredient))} Vorrat umschalten" aria-pressed="${s.pantry.has(p.ingredient)}">${s.pantry.has(p.ingredient)?'✓':'+'}</button></td></tr>`).join('')}</tbody></table></div><h3 class="mk-spacer">So geht’s</h3><ol>${(r.methodSteps||[r.method]).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p><b>Anwendung:</b> ${esc(r.serving||'Vorsichtig dosieren und abschmecken.')}</p><div class="mk-actions">${canMix(r)?button('In Mischküche anpassen →','mix',r.id,'primary'):''}${button('Fehlende Zutaten merken','missing',r.id)}${button('Rezept kopieren','copy-recipe',r.id)}</div>${!canMix(r)&&r.kind==='Trockenmischung'?'<p class="mk-muted">Für diese Rezeptur liegen nicht für alle Zutaten belastbare Löffel-zu-Gramm-Richtwerte vor. Verwende den Originalansatz oder entwickle eine eigene Grammrezeptur.</p>':''}${recipeNotes(r)}${recipeSources(r)}<p class="mk-muted">${esc(r.reviewStatus||'Redaktionell zusammengestellt, keine garantierte Originalrezeptur.')} · Allergene und Spurenangaben der Einzelzutaten beachten.</p>`);}
function dialog(content){return `<div class="mk-backdrop" data-action="overlay"><section class="mk-dialog" role="dialog" aria-modal="true" aria-label="Gewürzdetails" tabindex="-1"><button class="mk-close" data-action="close" aria-label="Schließen">×</button>${content}</section></div>`;}
function floatingBanner(){return `<aside class="mk-floating-banner" aria-label="Dein Gewürzregal – Schnellzugriff"><div class="mk-floating-brand"><img src="${base}assets/mein-kraut-logo-192.webp?v=final-1" alt="Mein Kraut – Original-Logo" width="68" height="68"><span><b>Mein Kraut.</b><span lang="en">My Spice. Your Taste.</span></span></div><div class="mk-floating-actions">${nav('Entdeckungsreise','laender','primary')}${nav('Startseite','start')}</div></aside>`;}
function render(focus=false){const pages={start:home,rezepte:recipeList,regal:pantry,laender:countries,regionen:regions,werkstatt:workshop,wissen:knowledge,dosen:kit,kosten:costs,meine:savedMixes,einkauf:shopping,shop:()=>window.MEINKRAUT_COMMERCE.renderPage('shop'),premium:()=>window.MEINKRAUT_COMMERCE.renderPage('premium'),refill:()=>window.MEINKRAUT_COMMERCE.renderPage('refill'),warenkorb:()=>window.MEINKRAUT_COMMERCE.renderPage('warenkorb'),etiketten:()=>window.MEINKRAUT_COMMERCE.renderPage('etiketten'),konto:()=>window.MEINKRAUT_COMMERCE.renderPage('konto')};root.innerHTML=header()+`<main class="mk-main" id="mk-main" tabindex="-1">${(pages[s.page]||home)()}</main>`+footer()+floatingBanner()+modal()+'<div class="mk-print-sheet" id="mk-print-sheet"></div><input id="mk-import-file" type="file" accept="application/json,.json" hidden>';
if(s.modal){document.body.style.overflow='hidden';if(focus)root.querySelector('.mk-dialog')?.focus();}else document.body.style.overflow='';window.MEINKRAUT_COMMERCE?.afterRender();}
function navigate(page,reset=true){s.menuOpen=false;if(reset){s.search='';s.pageNo=1;s.ownedOnly=false;}s.page=page;s.modal='';history.replaceState(null,'','#'+page);render();root.querySelector('#mk-main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function toast(t){root.querySelector('.mk-toast')?.remove();const n=document.createElement('div');n.className='mk-toast';n.setAttribute('role','status');n.textContent=t;root.append(n);setTimeout(()=>n.remove(),4500);}
function copy(t){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>toast('Kopiert.')).catch(()=>toast('Kopieren ist hier nicht verfügbar. Nutze die Druckansicht.'));else toast('Kopieren ist hier nicht verfügbar. Nutze die Druckansicht.');}
function close(){s.modal='';render();if(dialogOpener?.id){root.querySelector(`[data-action="${dialogOpener.action}"][data-id="${CSS.escape(dialogOpener.id)}"]`)?.focus();}}
function printWork(){const rows=currentRows().filter(p=>p.amount>0);if(!rows.length){toast('Ergänze mindestens eine Zutat mit positiver Menge.');return;}const sheet=root.querySelector('#mk-print-sheet');sheet.innerHTML=`<div class="mk-print-label"><img src="${logo}" alt="Mein Kraut"><h2>${esc(s.customName)}</h2><p>${number(s.target)} g · Gemischt am ${esc(s.labelDate)}</p><p>Zutaten: ${rows.slice().sort((a,b)=>b.amount-a.amount).map(p=>esc(name(p.id))).join(', ')}.</p><p>Trocken, kühl, lichtgeschützt und luftdicht lagern.</p><div class="mk-label-source">Mein Kraut · meinkraut.odpc.de</div></div><section class="mk-print-instructions"><h2>${esc(s.customName)} – deine Rezeptur</h2><ul>${rows.map(p=>`<li>${number(p.amount)} g ${esc(name(p.id))} (${number(p.percent,1)} %)</li>`).join('')}</ul><p>Digitalwaage verwenden. Bei sehr kleinen Mengen Feinwaage nutzen oder einen größeren Ansatz herstellen.</p><p>Nur vollständig trockene Zutaten als trockenen Vorrat abfüllen. Allergene und Spuren der Einzelzutaten prüfen.</p></section>`;window.print();}
function exportState(){const data={schema:2,commerce:window.MEINKRAUT_COMMERCE?.backup(),exportedAt:new Date().toISOString(),pantry:[...s.pantry],basket:[...s.basket],favorites:[...s.favorites],saved:s.saved,prices:s.prices};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mein-kraut-regal.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
root.addEventListener('click',e=>{const el=e.target.closest('[data-nav],[data-action]');if(!el||!root.contains(el))return;if(el.dataset.nav){navigate(el.dataset.nav);return;}const a=el.dataset.action,id=el.dataset.id;if(a==='menu'){s.menuOpen=!s.menuOpen;render();return;}
if(a==='recipe'||a==='ingredient'){dialogOpener={action:a,id};s.modal=a==='ingredient'?'ingredient:'+id:id;s.recipeFactor=1;render(true);return;}
if(a==='close'){close();return;}if(a==='overlay'){if(e.target===el)close();return;}
if(a==='pantry'){s.pantry.has(id)?s.pantry.delete(id):s.pantry.add(id);if(s.pantry.has(id))s.basket.delete(id);save();render();return;}
if(a==='favorite'){s.favorites.has(id)?s.favorites.delete(id):s.favorites.add(id);save();render();return;}
if(a==='mix'){startMix(recipeMap.get(id));return;}if(a==='blank'){s.parts=[{id:'paprika-edelsu',grams:1,enabled:true}];s.workRecipe=null;s.customName='Meine Mischung';window.MEINKRAUT_COMMERCE?.syncLabelName(s.customName);s.target=50;s.checked.clear();navigate('werkstatt');return;}
if(a==='mix-refill'){window.MEINKRAUT_COMMERCE?.prepareMix(currentRows().filter(p=>p.enabled&&p.amount>0),s.pantry);return;}
if(a==='saved-refill'){const m=s.saved.find(r=>r.id===id);if(m){s.parts=structuredClone(m.parts);s.target=m.target;s.customName=m.name;window.MEINKRAUT_COMMERCE?.prepareMix(currentRows().filter(p=>p.enabled&&p.amount>0),s.pantry);}return;}
if(a==='target'){s.target=Number(id);render();return;}
if(a==='add-part'){const id=root.querySelector('#mk-add-ingredient')?.value;if(id&&ingredients.has(id)&&dryIngredient(ingredients.get(id))&&!s.parts.some(p=>p.id===id)){s.parts.push({id,grams:1,enabled:true});render();}return;}
if(a==='save-mix'){const rows=currentRows().filter(p=>p.amount>0);if(!rows.length){toast('Mindestens eine Zutat mit positiver Menge ist erforderlich.');return;}if(s.saved.length>=200){toast('Dein Regal enthält bereits 200 Mischungen. Exportiere sie und entferne ältere Varianten.');return;}const mix={id:crypto.randomUUID?.()||'mix-'+Date.now(),name:s.customName.trim()||'Meine Mischung',parts:rows.map(p=>({id:p.id,grams:p.amount,enabled:true})),target:s.target,date:s.labelDate,label:window.MEINKRAUT_COMMERCE?.labelSnapshot()};s.saved.unshift(mix);if(save())toast('Deine Mischung ist auf diesem Gerät gespeichert.');return;}
if(a==='load-mix'){const m=s.saved.find(r=>r.id===id);if(m){s.parts=structuredClone(m.parts);s.target=m.target;s.customName=m.name;if(m.label)window.MEINKRAUT_COMMERCE?.loadLabel(m.label);else window.MEINKRAUT_COMMERCE?.syncLabelName(m.name);s.workRecipe=null;s.checked.clear();navigate('werkstatt');}return;}
if(a==='delete-mix'){s.saved=s.saved.filter(r=>r.id!==id);save();render();toast('Mischung entfernt. Deine übrigen Rezepturen bleiben erhalten.');return;}
if(a==='missing'||a==='missing-work'){const ids=a==='missing'?recipeMap.get(id).ingredients.map(p=>p.ingredient):currentRows().filter(p=>p.enabled&&p.amount>0).map(p=>p.id);let n=0;ids.forEach(x=>{if(!s.pantry.has(x)){s.basket.add(x);n++;}});save();toast(n?n+' fehlende Zutaten auf der Einkaufsliste.':'Alle Zutaten sind im Regal markiert.');return;}
if(a==='remove-basket'){s.basket.delete(id);save();render();return;}
if(a==='copy-shopping'){copy([...s.basket].map(id=>'□ '+name(id)).join('\n')||'Die Einkaufsliste ist leer.');return;}
if(a==='print-shopping'){root.querySelector('#mk-print-sheet').innerHTML='<h2>Mein Kraut – Einkaufsliste</h2><ul>'+[...s.basket].map(id=>'<li>'+esc(name(id))+'</li>').join('')+'</ul>';window.print();return;}
if(a==='print-work'){printWork();return;}if(a==='export'){exportState();return;}if(a==='import'){root.querySelector('#mk-import-file').click();return;}
if(a==='copy-recipe'){const r=recipeMap.get(id);copy(recipeCopyText(r,s.recipeFactor));return;}
if(a==='region'){s.regionId=id;render();return;}if(a==='country'){s.countryCode=id;render();return;}if(a==='country-recipes'){s.country=id;navigate('rezepte');return;}
if(a==='ingredient-recipes'){s.kind='Alle';s.country='Alle';s.search=name(id);s.pageNo=1;s.modal='';s.page='rezepte';render();window.scrollTo({top:0,behavior:'instant'});return;}
if(a==='starter'){s.kind='Trockenmischung';s.pageNo=1;render();return;}if(a==='all-recipes'){s.kind='Alle';s.country='Alle';s.search='';s.ownedOnly=false;s.pageNo=1;render();return;}
if(a==='prev'||a==='next'){s.pageNo+=a==='next'?1:-1;render();root.querySelector('.mk-toolrow')?.scrollIntoView({block:'start'});return;}
if(a==='price-mix'){const r={id:'price-italian',name:'Meine italienischen Kräuter',kind:'Trockenmischung',countries:['IT'],ingredients:priceRows.map(([n,g])=>({ingredient:db.ingredients.find(i=>norm(i.name)===norm(n))?.id,amount:g,unit:'g'})),editorialType:'Eigene Beispielrezeptur',reviewStatus:'Redaktionell · nicht verkostet'};if(r.ingredients.every(p=>ingredients.has(p.ingredient)))startMix(r);return;}
});
let searchTimer;root.addEventListener('input',e=>{if(e.target.matches('[data-field="search"]')){s.search=e.target.value;s.pageNo=1;const pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const q=root.querySelector('[data-field="search"]');q?.focus();try{q?.setSelectionRange(pos,pos);}catch(_){}},180);return;}if(e.target.dataset.field==='customName'){s.customName=e.target.value;const labelName=root.querySelector('#mk-label-name');if(labelName)labelName.textContent=s.customName;window.MEINKRAUT_COMMERCE?.syncLabelName(s.customName);return;}});
root.addEventListener('change',async e=>{const el=e.target;if(el.id==='mk-import-file'){const f=el.files?.[0];if(!f)return;if(f.size>2e6){toast('Die Datei ist zu groß (maximal 2 MB).');return;}try{const j=JSON.parse(await f.text());if(![1,2].includes(j.schema)||!Array.isArray(j.pantry))throw Error();const mixes=Array.isArray(j.saved)?j.saved:[];if(mixes.length>200||!mixes.every(validateSaved))throw Error();if(j.commerce&&!window.MEINKRAUT_COMMERCE?.validateBackup(j.commerce))throw Error();s.pantry=validIds(j.pantry,ingredients);s.basket=validIds(j.basket,ingredients);s.favorites=validIds(j.favorites,recipeMap);s.saved=mixes;s.prices={};if(j.commerce)window.MEINKRAUT_COMMERCE.restoreBackup(j.commerce);save();render();toast('Regal, Mischungen und vorhandene Shopentwürfe importiert.');}catch(_){toast('Diese Datei enthält kein gültiges Mein-Kraut-Regal.');}return;}
if(el.dataset.partToggle!==undefined){s.parts[Number(el.dataset.partToggle)].enabled=el.checked;render();return;}if(el.dataset.partGrams!==undefined){const v=Number(el.value);if(!Number.isFinite(v)||v<0||v>10000){el.value=s.parts[Number(el.dataset.partGrams)].grams;return;}s.parts[Number(el.dataset.partGrams)].grams=v;render();return;}if(el.dataset.step!==undefined){el.checked?s.checked.add(Number(el.dataset.step)):s.checked.delete(Number(el.dataset.step));return;}
const k=el.dataset.field;if(!k||k==='search'||k==='customName')return;if(k==='target'){const n=Number(el.value);if(!Number.isFinite(n)||n<1||n>5000){el.value=s.target;toast('Wähle eine Menge zwischen 1 und 5.000 Gramm.');return;}s.target=n;}else if(k==='recipeFactor')s.recipeFactor=Number(el.value);else s[k]=el.type==='checkbox'?el.checked:el.value;s.pageNo=1;render();});
document.addEventListener('keydown',e=>{if(!s.modal)return;if(e.key==='Escape'){close();return;}if(e.key==='Tab'){const dialog=root.querySelector('.mk-dialog'),els=[...dialog.querySelectorAll('button,input,select,a[href],summary')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
const hash=location.hash.slice(1),allowed=['start','rezepte','werkstatt','laender','regionen','regal','wissen','dosen','kosten','meine','einkauf','shop','premium','refill','warenkorb','etiketten','konto'];if(allowed.includes(config.page))s.page=config.page;if(allowed.includes(hash))s.page=hash;
window.MEINKRAUT_BRIDGE={navigate,refresh:()=>{render();window.MEINKRAUT_COMMERCE?.afterRender();},getState:()=>s,exportSnapshot:()=>({pantry:[...s.pantry],basket:[...s.basket],favorites:[...s.favorites],saved:s.saved,prices:s.prices}),importSnapshot:x=>{if(!x||!Array.isArray(x.pantry)||!Array.isArray(x.saved)||!x.saved.every(validateSaved))return false;s.pantry=validIds(x.pantry,ingredients);s.basket=validIds(x.basket,ingredients);s.favorites=validIds(x.favorites,recipeMap);s.saved=x.saved.slice(0,200);s.prices=x.prices||{};return save();}};
if(config.bootMix&&recipeMap.has(config.bootMix)){const recipe=recipeMap.get(config.bootMix);if(canMix(recipe))startMix(recipe);else{s.modal=config.bootMix;s.page='rezepte';}}
if(window.MEINKRAUT_DEBUG)window.MEINKRAUT_TEST={currentRows,partsFromRecipe,canMix,recipeCopyText,conversion,validateSaved,getState:()=>s,render,counts:()=>({ingredients:ingredients.size,recipes:recipes.length,countries:db.countries.length})};
render();window.MEINKRAUT_COMMERCE?.afterRender();
})();
